    # Color certain 2x2 blocks of the repeated pattern in blue (8).
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] != 2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p=(y+dy,x+dx)
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==2 and p not in seen:
              seen.add(p); stack.append(p)
        comps.append(cells)
    # The marked clusters are those that form a connected sequence of 2x2 tiles
    # with a shared side; preserve isolated tile examples as the reference pattern.
    for cells in comps:
      # Recolor blocks that are adjacent to another 2x2 block.
      coords=set(cells)
      if len(coords)>4:
        for y,x in coords: out[y][x]=8
    return out
