            for v in blocks:
                if v==a or v==b: continue
                va=(a[0]-v[0],a[1]-v[1]); vb=(b[0]-v[0],b[1]-v[1])
                if va[0]*vb[0]+va[1]*vb[1]==0 and abs(va[0])+abs(va[1])==abs(vb[0])+abs(vb[1]):
                    chosen.update((a,b))
    for r,c in chosen:
        for y in (r,r+1):
            for x in (c,c+1): out[y][x]=8
    return out
